function o(t){const n=Number(t);return Number.isFinite(n)?Math.min(255,Math.max(0,Math.round(n))):0}function e(t){return o(t).toString(16).padStart(2,"0")}function u(t){const n=/^#?([0-9a-f]{3}|[0-9a-f]{6})$/i.exec(String(t||"").trim());if(!n)return null;let r=n[1];return r.length===3&&(r=r.split("").map(i=>i+i).join("")),`#${r.toLowerCase()}`}function a(t){const n=/^rgba?\(\s*([+\-]?\d{1,3})\s*,\s*([+\-]?\d{1,3})\s*,\s*([+\-]?\d{1,3})(?:\s*,\s*(?:\d*\.?\d+))?\s*\)$/i.exec(String(t||"").trim());return n?`#${e(n[1])}${e(n[2])}${e(n[3])}`:null}function s(t,n="#0891b2"){const r=u(t)||a(t);return r||(n==null?null:u(n)||"#0891b2")}export{s as n};
